import type { FindingSeverity, JobStatus } from "@/lib/db/enums";
import type { Tables, TablesInsert } from "@/lib/db/types.generated";
import type { Db } from "@/lib/db/queries/papers";
import { enqueueJob } from "@/lib/db/queries/jobs";

/**
 * Defense-prep aggregate access — P11.
 *
 * Questions and groups are SELECT-only for users (generated by the worker under
 * the service role). Practices and answers are user-writable, so the practice
 * flow runs on the user-session client where RLS enforces ownership; answer
 * feedback (model output) is written under the service role.
 */

export type DefenseQuestionGroup = Tables<"defense_question_groups">;
export type DefenseQuestion = Tables<"defense_questions">;
export type DefensePractice = Tables<"defense_practices">;
export type DefenseAnswer = Tables<"defense_question_answers">;

export interface DefenseGroupWithQuestions extends DefenseQuestionGroup {
  questions: DefenseQuestion[];
}

export interface PracticeWithAnswers extends DefensePractice {
  answers: DefenseAnswer[];
}

function unwrap<T>(
  result: { data: T; error: null } | { data: null; error: { message: string } },
  context: string,
): T {
  if (result.error) {
    throw new Error(`${context}: ${result.error.message}`);
  }
  return result.data;
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

export async function getDefenseQuestions(
  db: Db,
  analysisId: string,
): Promise<DefenseGroupWithQuestions[]> {
  const result = await db
    .from("defense_question_groups")
    .select("*, questions:defense_questions(*)")
    .eq("paper_analysis_id", analysisId)
    .order("sort_order", { ascending: true })
    .order("sort_order", {
      referencedTable: "defense_questions",
      ascending: true,
    });

  return unwrap(
    result,
    "getDefenseQuestions",
  ) as unknown as DefenseGroupWithQuestions[];
}

/** Question count for the sub-nav badge. */
export async function getDefenseQuestionCount(
  db: Db,
  analysisId: string,
): Promise<number> {
  const groups = await getDefenseQuestions(db, analysisId);
  return groups.reduce((sum, group) => sum + group.questions.length, 0);
}

export async function listPractices(
  db: Db,
  analysisId: string,
): Promise<DefensePractice[]> {
  const result = await db
    .from("defense_practices")
    .select("*")
    .eq("paper_analysis_id", analysisId)
    .order("started_at", { ascending: false });
  return unwrap(result, "listPractices");
}

export async function getPractice(
  db: Db,
  practiceId: string,
): Promise<DefensePractice | null> {
  const result = await db
    .from("defense_practices")
    .select("*")
    .eq("id", practiceId)
    .maybeSingle();
  return unwrap(result, "getPractice");
}

export async function getPracticeWithAnswers(
  db: Db,
  practiceId: string,
): Promise<PracticeWithAnswers | null> {
  const result = await db
    .from("defense_practices")
    .select("*, answers:defense_question_answers(*)")
    .eq("id", practiceId)
    .maybeSingle();
  return unwrap(
    result,
    "getPracticeWithAnswers",
  ) as unknown as PracticeWithAnswers | null;
}

export async function getDefenseQuestion(
  db: Db,
  questionId: string,
): Promise<DefenseQuestion | null> {
  const result = await db
    .from("defense_questions")
    .select("*")
    .eq("id", questionId)
    .maybeSingle();
  return unwrap(result, "getDefenseQuestion");
}

export async function getAnswer(
  db: Db,
  practiceId: string,
  questionId: string,
): Promise<DefenseAnswer | null> {
  const result = await db
    .from("defense_question_answers")
    .select("*")
    .eq("defense_practice_id", practiceId)
    .eq("defense_question_id", questionId)
    .maybeSingle();
  return unwrap(result, "getAnswer");
}

// ---------------------------------------------------------------------------
// Status + generation writes (service role)
// ---------------------------------------------------------------------------

export async function setDefenseStatus(
  db: Db,
  analysisId: string,
  status: JobStatus,
): Promise<void> {
  const result = await db
    .from("paper_analyses")
    .update({ defense_status: status })
    .eq("id", analysisId);
  if (result.error)
    throw new Error(`setDefenseStatus: ${result.error.message}`);
}

/** Clears prior questions so a regeneration replaces rather than duplicates. */
export async function clearDefenseQuestions(
  db: Db,
  analysisId: string,
): Promise<void> {
  const result = await db
    .from("defense_question_groups")
    .delete()
    .eq("paper_analysis_id", analysisId);
  if (result.error)
    throw new Error(`clearDefenseQuestions: ${result.error.message}`);
}

export async function insertDefenseGroup(
  db: Db,
  args: {
    analysisId: string;
    paperId: string;
    title: string;
    description: string;
    sortOrder: number;
  },
): Promise<{ id: string }> {
  const result = await db
    .from("defense_question_groups")
    .insert({
      paper_analysis_id: args.analysisId,
      paper_id: args.paperId,
      title: args.title,
      description: args.description,
      sort_order: args.sortOrder,
    })
    .select("id")
    .single();
  return unwrap(result, "insertDefenseGroup");
}

export interface DefenseQuestionInsert {
  question: string;
  referenceAnswer: string;
  sourceQuote: string | null;
  pageNumber: number | null;
  difficulty: FindingSeverity;
  sortOrder: number;
}

export async function insertDefenseQuestions(
  db: Db,
  groupId: string,
  questions: readonly DefenseQuestionInsert[],
): Promise<number> {
  if (questions.length === 0) return 0;

  const rows: TablesInsert<"defense_questions">[] = questions.map(
    (question) => ({
      defense_question_group_id: groupId,
      question: question.question,
      reference_answer: question.referenceAnswer,
      source_quote: question.sourceQuote,
      page_number: question.pageNumber,
      difficulty: question.difficulty,
      sort_order: question.sortOrder,
    }),
  );

  const result = await db.from("defense_questions").insert(rows);
  if (result.error)
    throw new Error(`insertDefenseQuestions: ${result.error.message}`);
  return rows.length;
}

export async function requeueDefenseJob(
  db: Db,
  analysisId: string,
  uploadId: string,
): Promise<void> {
  const result = await db
    .from("analysis_jobs")
    .update({
      status: "NONE",
      attempts: 0,
      run_after: new Date().toISOString(),
      claimed_at: null,
      claimed_by: null,
      last_error: null,
      completed_at: null,
    })
    .eq("paper_analysis_id", analysisId)
    .eq("kind", "DEFENSE_QUESTIONS")
    .select("id");

  if (result.error)
    throw new Error(`requeueDefenseJob: ${result.error.message}`);
  if ((result.data?.length ?? 0) === 0) {
    await enqueueJob(db, {
      paperAnalysisId: analysisId,
      paperUploadId: uploadId,
      kind: "DEFENSE_QUESTIONS",
    });
  }
}

// ---------------------------------------------------------------------------
// Practice writes
// ---------------------------------------------------------------------------

export async function createPractice(
  db: Db,
  args: { analysisId: string; questionCount: number },
): Promise<{ id: string }> {
  const result = await db
    .from("defense_practices")
    .insert({
      paper_analysis_id: args.analysisId,
      question_count: args.questionCount,
    })
    .select("id")
    .single();
  return unwrap(result, "createPractice");
}

/** Records one answer (service role — feedback and score are model output). */
export async function insertAnswer(
  db: Db,
  args: {
    practiceId: string;
    questionId: string;
    answerText: string;
    feedback: string | null;
    score: number | null;
  },
): Promise<void> {
  const result = await db.from("defense_question_answers").upsert(
    {
      defense_practice_id: args.practiceId,
      defense_question_id: args.questionId,
      answer_text: args.answerText,
      feedback: args.feedback,
      score: args.score,
    },
    { onConflict: "defense_practice_id,defense_question_id" },
  );
  if (result.error) throw new Error(`insertAnswer: ${result.error.message}`);
}

export async function updatePracticeProgress(
  db: Db,
  practiceId: string,
  args: {
    answeredCount: number;
    averageScore: number | null;
    completed: boolean;
  },
): Promise<void> {
  const result = await db
    .from("defense_practices")
    .update({
      answered_count: args.answeredCount,
      average_score: args.averageScore,
      completed_at: args.completed ? new Date().toISOString() : null,
    })
    .eq("id", practiceId);
  if (result.error)
    throw new Error(`updatePracticeProgress: ${result.error.message}`);
}
